10	function CopyInline({ text }: { text: string }) {
11	  const [copied, setCopied] = useState(false);
12	  const handleCopy = async () => {
13	    try { await navigator.clipboard.writeText(text); } catch { /* fallback */ }
14	    setCopied(true);
15	    setTimeout(() => setCopied(false), 2000);
16	  };
17	  return (
18	    <button
19	      onClick={handleCopy}
20	      className={cn(
21	        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-[10px] font-medium border transition-all",
22	        copied
23	          ? "bg-green-50 text-green-600 border-green-200"
24	          : "bg-white text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground"
25	      )}
26	    >
27	      {copied ? <><Check className="h-2.5 w-2.5" />Copied</> : <><Copy className="h-2.5 w-2.5" />Copy</>}
28	    </button>
29	  );
30	}
