105	        </div>
106	
107	        {expanded && (
108	          <div className="mt-4 space-y-4 animate-fade-in">
109	            {/* Current state */}
110	            <div>
111	              <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-muted-foreground">
