115	                {finding.current_state}
116	              </div>
117	            </div>
118	
119	            {/* Recommendation */}
120	            <div>
121	              <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-muted-foreground">
122	                How to fix it
