56	
57	function getWeekLabel(date: Date): string {
58	  const now = new Date();
59	  const diffMs = now.getTime() - date.getTime();
60	  const diffWeeks = Math.floor(diffMs / (1000 * 60 * 60 * 24 * 7));
61	  if (diffWeeks === 0) return "This week";
62	  if (diffWeeks === 1) return "1w ago";
63	  return `${diffWeeks}w ago`;
64	}
65	
66	function getBucketFill(range: string): string {
67	  const fills: Record<string, string> = {
68	    "0-20": "#EF4444",
69	    "21-40": "#F87171",
70	    "41-60": "#F59E0B",
71	    "61-80": "#22C55E",
72	    "81-100": "#16A34A",
73	  };
74	  return fills[range] ?? "#94A3B8";
75	}
76	
77	function scoreToRange(score: number): string {
78	  if (score <= 20) return "0-20";
79	  if (score <= 40) return "21-40";
80	  if (score <= 60) return "41-60";
81	  if (score <= 80) return "61-80";
82	  return "81-100";
83	}
