1	import { useQuery } from "@tanstack/react-query";
2	import supabase from "@/lib/supabase";
3	import type { AuditLogRow } from "@/types/database";
4	
5	export interface AuditLogEntry extends AuditLogRow {
6	  admin_email?: string;
7	  admin_name?: string;
8	}
9	
10	interface FetchAuditLogParams {
11	  page: number;
12	  pageSize: number;
13	  actionFilter?: string;
14	}
15	
16	async function fetchAuditLog({
17	  page,
18	  pageSize,
19	  actionFilter,
20	}: FetchAuditLogParams): Promise<{ entries: AuditLogEntry[]; total: number }> {
21	  let query = supabase
22	    .from("audit_logs")
23	    .select(
24	      `
25	      *,
26	      profiles:admin_id (
27	        email,
28	        full_name
29	      )
30	    `,
31	      { count: "exact" }
32	    )
33	    .order("created_at", { ascending: false });
34	
35	  if (actionFilter) {
36	    query = query.eq("action", actionFilter);
37	  }
38	
39	  const from = page * pageSize;
40	  const to = from + pageSize - 1;
41	  query = query.range(from, to);
42	
43	  const { data, count, error } = await query;
44	
45	  if (error) throw new Error(error.message);
46	
47	  const entries: AuditLogEntry[] = (data ?? []).map((row) => {
48	    // Supabase returns the joined profile as a nested object
49	    const profileData = row.profiles as
50	      | { email: string; full_name: string }
51	      | null;
52	    return {
53	      id: row.id,
54	      admin_id: row.admin_id,
55	      action: row.action,
56	      target_type: row.target_type,
57	      target_id: row.target_id,
58	      metadata: row.metadata as Record<string, unknown>,
59	      created_at: row.created_at,
60	      admin_email: profileData?.email,
61	      admin_name: profileData?.full_name,
62	    };
63	  });
64	
65	  return { entries, total: count ?? 0 };
66	}
