7	export function useCountUp(target: number, duration: number = 1200): number {
8	  const [value, setValue] = useState(0);
9	  const startTime = useRef<number | null>(null);
10	  const rafId = useRef<number>(0);
11	
12	  useEffect(() => {
13	    startTime.current = null;
14	
15	    const animate = (timestamp: number) => {
16	      if (startTime.current === null) startTime.current = timestamp;
17	      const elapsed = timestamp - startTime.current;
18	      const progress = Math.min(elapsed / duration, 1);
19	
20	      // Ease-out cubic for smooth deceleration
21	      const eased = 1 - Math.pow(1 - progress, 3);
22	      setValue(Math.round(eased * target));
23	
24	      if (progress < 1) {
25	        rafId.current = requestAnimationFrame(animate);
26	      }
27	    };
28	
29	    rafId.current = requestAnimationFrame(animate);
30	
31	    return () => cancelAnimationFrame(rafId.current);
32	  }, [target, duration]);
33	
34	  return value;
