### 4.3 — Add Error Boundaries Around Charts

**Current state:** No `ErrorBoundary` components exist anywhere in the codebase (confirmed by grep). Recharts throws if data is malformed (e.g., `NaN` in the score array, empty `scoreDistribution`). A chart error cascades to unmount the entire `Dashboard` or `AuditReport` page.

**What to change:**
Create `src/components/shared/ChartErrorBoundary.tsx` as a React class component:

```typescript
import { Component, type ErrorInfo, type ReactNode } from "react";
import { AlertTriangle } from "lucide-react";

interface Props {
  children: ReactNode;
  fallbackHeight?: number;
}

interface State {
  hasError: boolean;
}

export class ChartErrorBoundary extends Component<Props, State> {
  state: State = { hasError: false };

  static getDerivedStateFromError(): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("Chart render error:", error, info);
  }

  render() {
    if (this.state.hasError) {
      const height = this.props.fallbackHeight ?? 120;
      return (
        <div
          className="flex items-center justify-center gap-2 rounded-lg border border-border/40 bg-muted/20 text-xs text-muted-foreground"
          style={{ height }}
        >
          <AlertTriangle className="h-3.5 w-3.5" />
          Chart unavailable
        </div>
      );
    }
    return this.props.children;
  }
}
```

Wrap each Recharts `ResponsiveContainer` in `Dashboard.tsx` and `AuditReport.tsx` with `<ChartErrorBoundary fallbackHeight={90}>`.

